/**
 * The domain database, and the questions both engines ask of it.
 *
 * The names lived in three places and none of them knew anything: a
 * 900-line `hostPools` map in the AmneziaWG generator, a `MASQUERADE_HOSTS`
 * array in the XRay transport module, and a `dest` hard-coded into the XRay
 * defaults. All three were flat lists of strings, picked once and never
 * re-checked — which is how the default REALITY donor came to be a site
 * behind Cloudflare, the one CDN a donor must not share with the server
 * imitating it.
 *
 * Here a domain is a record with facts attached and a date on the facts, and
 * the pools are queries rather than lists. `scripts/probe.ts`
 * establishes the facts; `DOMAINS` records what it found.
 *
 * WHERE `whitelistedIn` COMES FROM, AND HOW FAR TO TRUST IT
 *
 * Not from a probe: no packet establishes whether a regulator has exempted a
 * host. It is a citation, and a weaker one than the rest of this file:
 *
 *   - Russia's «Доступный интернет» registry is official but nearly empty —
 *     reporting since 2022 puts it at two entries, Gosuslugi and VK, down
 *     from around 391 in early 2020.
 *   - The 2025 mobile-shutdown whitelist is the one that matters in practice
 *     and is *not* published in full by anyone official. What exists is a
 *     ministry announcement naming organisations, later media-reported
 *     expansions, and community lists compiled by scanning during actual
 *     shutdowns — e.g. github.com/hxehex/russia-mobile-internet-whitelist.
 *   - Every source names brands rather than hostnames, so the mapping from
 *     "Альфа-банк" to `alfabank.ru` is an inference, not a quotation.
 *
 * So these marks are the best available reading of a list nobody publishes,
 * and they should be re-checked rather than inherited. They are worth having
 * anyway: a whitelisted name is plausible traffic exactly when the network is
 * degraded, which is when this tool is used.
 */

import { cryptoPick } from "./rng";
import type {
  DnsQueryType,
  DomainCdn,
  DomainQuery,
  DomainRecord,
  DomainRegion,
  DomainRole,
  DomainServices,
  Fact,
} from "@/types/domain";

export type {
  DnsQueryType,
  DomainCdn,
  DomainQuery,
  DomainRecord,
  DomainRegion,
  DomainRole,
  DomainServices,
  Fact,
} from "@/types/domain";

/* ── Asking the database ──────────────────────────────────────────────────── */

/** Every role there is, which is also the order a report lists them in. */
export const ALL_ROLES: readonly DomainRole[] = [
  "donor", "quic", "tls", "dtls", "sip", "stun",
  "dns", "resolver", "doh", "dot", "smtp", "imap", "pop3", "ntp", "ssh",
];

/**
 * Does a host meet what a role needs?
 *
 * The requirements are the protocols' own, not preferences:
 *
 *   - `donor` — a REALITY `dest` borrows the site's TLS 1.3 handshake and
 *     needs HTTP/2 to be plausible. It must serve at its own name rather than
 *     redirect away, and must not sit behind a CDN, because sharing one with
 *     the server that imitates it is how the disguise fails.
 *   - `quic` — a QUIC or HTTP/3 mimicry packet aimed at a host with no HTTP/3
 *     is a packet nobody could have sent.
 *   - `tls` — needs TLS 1.3, which is what the imitated ClientHello offers.
 *   - `dns` — the QNAME of a query, so the name has to answer the QTYPE being
 *     asked. Every other role is a service on its own port, asked its own way.
 */
export function meetsRole(
  domain: DomainRecord,
  role: DomainRole,
  allowUnknown = false,
  dnsType?: DnsQueryType,
): boolean {
  const ok = (fact: Fact | undefined) =>
    fact === "yes" || (allowUnknown && (fact === "unknown" || fact === undefined));

  const service = (key: keyof DomainServices) =>
    ok(domain.services?.[key] as Fact | undefined);

  switch (role) {
    case "donor":
      return ok(domain.tls13) && ok(domain.h2) && ok(domain.serves) && domain.cdn === "none";
    case "quic":
      return ok(domain.h3);
    case "tls":
      return ok(domain.tls13);

    case "dns": {
      // A DNS query carries a name and a type, and the two have to agree. A
      // query for MX on a name that has never had one is a question no
      // resolver is asked twice — which is the whole point of recording which
      // types a name actually answers.
      const answers = domain.dnsAnswers;
      if (!answers?.length) return allowUnknown;
      return dnsType ? answers.includes(dnsType) : true;
    }

    case "resolver": {
      if (!ok(domain.services?.dns)) return false;
      if (!dnsType) return true;
      // Resolvers are picky in ways that show: one that refuses TXT answers a
      // TXT query with REFUSED, which is louder than sending nothing.
      const types = domain.services?.dnsTypes;
      if (!types) return allowUnknown;
      return types.includes(dnsType);
    }

    // The rest are services on their own ports, invisible to an HTTPS probe
    // and unknown until something asks. An unknown SIP host named in a SIP
    // packet is exactly the imitation that falls apart under inspection.
    case "dtls": return service("dtls");
    case "sip": return service("sip");
    case "stun": return service("stun");
    case "doh": return service("doh");
    case "dot": return service("dot");
    case "smtp": return service("smtp");
    case "imap": return service("imap");
    case "pop3": return service("pop3");
    case "ntp": return service("ntp");
    case "ssh": return service("ssh");
  }
}

/** Every role a domain qualifies for. A host is usually good for several. */
export function rolesOf(
  domain: DomainRecord,
  allowUnknown = false,
): readonly DomainRole[] {
  return ALL_ROLES.filter((role) => meetsRole(domain, role, allowUnknown));
}

/**
 * Answers already worked out, keyed by the question.
 *
 * The database is fixed at build time, so the same query always has the same
 * answer and there is no invalidation to get wrong. Worth caching because the
 * callers are not one-off: the generator asks per packet, and the panel that
 * shows example hosts asks once per role per recompute — fourteen sweeps of
 * two and a half thousand records every time the profile changes.
 */
const answers = new Map<string, readonly DomainRecord[]>();

function cacheKey(query: DomainQuery): string {
  const { regions, role, dnsType, excludeCdn, whitelistedIn, allowUnknown } = query;
  return [
    regions?.join("+") ?? "",
    role ?? "",
    dnsType ?? "",
    excludeCdn?.join("+") ?? "",
    whitelistedIn ?? "",
    allowUnknown ? "1" : "",
  ].join("|");
}

/** Every domain matching a query, in database order. */
export function findDomains(query: DomainQuery = {}): readonly DomainRecord[] {
  const key = cacheKey(query);
  const known = answers.get(key);
  if (known) return known;

  const { regions, role, dnsType, excludeCdn, whitelistedIn, allowUnknown = false } = query;

  const found = DOMAINS.filter((domain) => {
    if (regions?.length && !domain.regions.some((r) => regions.includes(r))) {
      return false;
    }
    if (whitelistedIn && !domain.whitelistedIn?.includes(whitelistedIn)) return false;
    if (excludeCdn?.length && excludeCdn.includes(domain.cdn)) return false;
    if (role && !meetsRole(domain, role, allowUnknown, dnsType)) return false;
    return true;
  });

  answers.set(key, found);
  return found;
}

/** The names for a query, cached beside the records for the same reason. */
const names = new Map<string, readonly string[]>();

/** Hostnames matching a query — what the generators actually want. */
export function hostsFor(query: DomainQuery = {}): readonly string[] {
  const key = cacheKey(query);
  const known = names.get(key);
  if (known) return known;

  const found = findDomains(query).map((d) => d.host);
  names.set(key, found);
  return found;
}

/**
 * One host matching a query.
 *
 * Falls back to widening the query rather than returning nothing: a
 * generator with no host to name cannot produce a packet at all, and a
 * less-perfect name beats no name. The widening is reported by the caller,
 * not hidden — see `pickHostStrict` when a wrong answer is worse than none.
 */
export function pickHost(query: DomainQuery = {}): string {
  const exact = hostsFor(query);
  if (exact.length) return cryptoPick(exact);

  const relaxed = hostsFor({ ...query, allowUnknown: true });
  if (relaxed.length) return cryptoPick(relaxed);

  const anyRegion = hostsFor({ role: query.role, allowUnknown: true });
  return anyRegion.length ? cryptoPick(anyRegion) : DOMAINS[0]!.host;
}

/** One host, or null when nothing genuinely qualifies. */
export function pickHostStrict(query: DomainQuery = {}): string | null {
  const hosts = hostsFor(query);
  return hosts.length ? cryptoPick(hosts) : null;
}

/** What the database knows, for the UI and for a coverage report. */
export function domainStats(): {
  total: number;
  byRegion: Record<string, number>;
  byRole: Record<DomainRole, number>;
  verified: number;
} {
  const byRegion: Record<string, number> = {};
  for (const domain of DOMAINS) {
    for (const region of domain.regions) {
      byRegion[region] = (byRegion[region] ?? 0) + 1;
    }
  }

  const byRole = Object.fromEntries(
    ALL_ROLES.map((role) => [role, findDomains({ role }).length]),
  ) as Record<DomainRole, number>;

  return {
    total: DOMAINS.length,
    byRegion,
    byRole,
    verified: DOMAINS.filter((d) => d.checked).length,
  };
}

/* ── The database ─────────────────────────────────────────────────────────── */

/**
 * Types one record where it is written, and nothing else.
 *
 * An array literal of fifteen hundred objects makes TypeScript infer a union
 * of fifteen hundred literal types before it ever looks at the annotation on
 * the variable, and it gives up: "union type that is too complex to
 * represent". Naming the type at each element means there is no union to
 * build. The call disappears at compile time.
 */
const d = (record: DomainRecord): DomainRecord => record;

