/** Hosts whose measurement did not take the ordinary path from its vantage. */
export const ROUTED_HOSTS: readonly string[] = [
  "cloudflare.com",
  "www.cloudflare.com",
  "github.com",
  "api.github.com",
  "raw.githubusercontent.com",
  "objects.githubusercontent.com",
  "discord.com",
  "cdn.discordapp.com",
  "matrix.org",
  "telegram.org",
  "web.telegram.org",
  "t.me",
];

/** Is this host one whose reading came through a tunnel rather than directly? */
export function isRouted(host: string): boolean {
  return ROUTED_HOSTS.some((r) => host === r || host.endsWith(`.${r}`));
}

/** CDNs a REALITY donor should not sit behind. */
export const DONOR_EXCLUDED_CDNS: readonly DomainCdn[] = [
  "cloudflare",
  "cloudfront",
  "akamai",
  "fastly",
];

/** Regions the UI offers, in the order it offers them. */
export const REGIONS: readonly DomainRegion[] = ["ru", "global", "eu", "uk", "by", "cn"];
